window.AUTH=window.AUTH||{};window.AUTH["18-8369"]={"d":"18-8369","id":"2019/18-8369","n":"Lomax v. Ortiz-Marquez","briefs":[{"k":"petitioner","label":"Brief of petitioner Arthur Lomax","date":"2019-12-09","url":"https://www.supremecourt.gov/DocketPDF/18/18-8369/124929/20191209151533100_Lomax%20Opening%20Brief_18-8369.PDF","side":"pet","n":95},{"k":"respondent","label":"Brief of respondents Christina Ortiz-Marquez, et al.","date":"2020-01-15","url":"https://www.supremecourt.gov/DocketPDF/18/18-8369/128724/20200115153013774_18-8369%20Brief%20for%20Respondents.pdf","side":"res","n":69},{"k":"united-states","label":"Brief amicus curiae of United States","date":"2020-01-22","url":"https://www.supremecourt.gov/DocketPDF/18/18-8369/129607/20200122175116720_18-8369bsacUnitedStates%20corrected.pdf","side":"us","n":68},{"k":"reply","label":"Reply of petitioner Arthur Lomax","date":"2020-02-14","url":"https://www.supremecourt.gov/DocketPDF/18/18-8369/133122/20200214152642617_Lomax_Reply%20Brief%20for%20Petitioner.pdf","side":"pet","n":46}],"opinion":"https://www.supremecourt.gov/opinions/preliminaryprint/590US2PP_web.pdf#page=183","tr":true,"items":[{"t":"case","label":"Abdul-Akbar v. McKelvie","cite":"239 F.3d 307","y":2001,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/239/307/","by":{"0":"40","1":"39","2":"32"}},{"t":"case","label":"Abdul-Akbar v. Watson","cite":"901 F.2d 329","y":1990,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.2d/901/329/","by":{"0":"39"}},{"t":"case","label":"Adkins v. E.I. DuPont de Nemours & Co.","cite":"335 U.S. 331","y":1948,"id":"scdb/1948-006","sc":1,"sum":"The court was justified in looking further to see if the costs really should have been $4,000 and, if not, in requiring affidavits made with an appreciation of the lesser amount of expense.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"3"}},{"t":"case","label":"Amaker v. Weiner","cite":"179 F.3d 48","y":1999,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/179/48/","by":{"0":"33"}},{"t":"case","label":"Arrowsmith v. United Press Int’l","cite":"320 F.2d 219","y":1963,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/320/219/","by":{"0":"16"}},{"t":"case","label":"Ashcroft v. Iqbal","cite":"556 U.S. 662","y":2009,"id":"2008/07-1015","sc":1,"sum":"The Court found that high-ranking government officials were not liable for unconstitutional acts by subordinate officials.","sumSrc":"Oyez","by":{"0":"15"}},{"t":"case","label":"Bargher v. White","cite":"928 F.3d 439","y":2019,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/928/439/","by":{"0":"30"}},{"t":"case","label":"Boddie v. Connecticut","cite":"401 U.S. 371","y":1971,"id":"1969/27","sc":1,"sum":"The Court reversed the District Court and held the fee requirement unconstitutional. In a majority opinion authored by Justice John M. Harlan, the Court recognized the importance of \"access to the courts\" for Boddie, as state court was the only method of obtaining a divorce in Connecticut.","sumSrc":"Oyez","by":{"0":"38"}},{"t":"case","label":"Booth v. Churner","cite":"206 F.3d 289","y":2000,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/206/289/","by":{"0":"30"}},{"t":"case","label":"Bounds v. Smith","cite":"430 U.S. 817","y":1977,"id":"1976/75-915","sc":1,"sum":"The Court held that the constitution required the North Carolina Department of Correction to provide prisoners with legal assistance as part of prisoners’ right of access to the courts. Justice Marshall emphasized that prisoners have a well-established right of adequate, effective and meaningful access to the courts.","sumSrc":"Oyez","by":{"0":"37","2":"31"}},{"t":"case","label":"Bruce v. Samuels","cite":"136 S. Ct. 627","y":2016,"id":"2015/14-844","sc":1,"sum":"A case in which the Court will determine whether the Prison Litigation Reform Act caps the monthly payment to cover a prisoner’s filing fees at 20% of the prisoner’s monthly income regardless of the number of pending cases the prisoner has in federal courts.","sumSrc":"Oyez","by":{"0":"7, 43","1":"5","2":"1"}},{"t":"case","label":"Butler v. Dep’t of Justice","cite":"492 F.3d 440","y":2007,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/492/440/","sum":"Holding that a dismissal for failure to prosecute did not count as a strike because it was “made without regard to the merits of the claim”.","sumSrc":"brief:0","by":{"0":"22, 25, 26, 43"}},{"t":"case","label":"Carson v. Johnson","cite":"112 F.3d 818","y":1997,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/112/818/","by":{"0":"40","2":"32"}},{"t":"case","label":"Carter v. Norfolk Cmty. Hosp. Ass’n, Inc.","cite":"761 F.2d 970","y":1985,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.2d/761/970/","by":{"0":"17"}},{"t":"case","label":"Cass Cty. v. Leech Lake Band of Chippewa Indians","cite":"524 U.S. 103","y":1998,"id":"1997/97-174","sc":1,"sum":"The Court held that ad valorem taxes may be imposed upon such land. \"When Congress makes Indian reservation land freely alienable, it manifests an unmistakably clear intent to render such land subject to state and local taxation,\" wrote Justice Thomas. Repurchasing the land by an Indian tribe does not return the land to tax-exempt status.","sumSrc":"Oyez","by":{"0":"26"}},{"t":"case","label":"Chaidez v. Ford Motor Co.","cite":"937 F.3d 998","y":2019,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/937/998/","by":{"0":"30"}},{"t":"case","label":"Clark v. Martinez","cite":"543 U.S. 371","y":2005,"id":"2004/03-878","sc":1,"sum":"The Court said the requirement that immigrants be detained no longer than reasonably necessary for deportation applied to both admissible and inadmissible immigrants. Because readmission to Cuba was unforeseeable, the detentions of Martinez and Benitez were unreasonable.","sumSrc":"Oyez","by":{"0":"37","1":"40","3":"21"}},{"t":"case","label":"Coleman v. Tollefson","cite":"135 S. Ct. 1759","y":2015,"id":"2014/13-1333","sc":1,"ar":2,"sum":"The Court held that a district court’s dismissal of a lawsuit counts as a “strike” for the purpose of the Prison Litigation Reform Act’s “three strikes” provision when the case is pending on appeal.","sumSrc":"Oyez","by":{"0":"passim","1":"2, 8, 12, 14","2":"1, 2, 9, 13, 14, 26","3":"7, 8, 9"}},{"t":"case","label":"Cooter & Gell v. Hartmarx Corp.","cite":"496 U.S. 384","y":1990,"id":"1989/89-275","sc":1,"sum":"Respondents, the defendants in a District Court suit instituted by petitioner law firm on behalf of a client, filed a motion to dismiss the complaint as having no basis in fact and a motion for sanctions under Federal Rule of Civil Procedure 11 on the ground that the firm had not made sufficient prefiling inquiries to support the complaint's allegations. Rule 11-after specifying, interalia, that an attorney's …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"14, 16, 21, 26"}},{"t":"case","label":"Crisafi v. Holland","cite":"655 F.2d 1305","y":1981,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/655/1305/","by":{"0":"22"}},{"t":"case","label":"Curry v. Yachera","cite":"835 F.3d 373","y":2016,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/835/373/","sum":"Holding that dismissing a Heck-barred action “with prejudice” was in error, and collecting decisions in support.","sumSrc":"brief:0","by":{"0":"33"}},{"t":"case","label":"Daker v. Comm’r, Ga. Dep’t of Corr.","cite":"820 F.3d 1278","y":2016,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/820/1278/","sum":"Holding that dismissals for want of prosecution and lack of jurisdiction, respectively, did not count as strikes.","sumSrc":"brief:0","by":{"0":"18, 25","3":"6, 12, 15"}},{"t":"case","label":"Day v. Maynard","cite":"200 F.3d 665","y":1999,"url":"https://www.courtlistener.com/c/F.3d/200/665/","op":1,"by":{"0":"36"}},{"t":"case","label":"Day v. Toner","cite":"530 F. App’x 118","y":2013,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/530/118/","by":{"0":"22"}},{"t":"case","label":"Denton v. Hernandez","cite":"504 U.S. 25","y":1992,"id":"1991/90-1846","sc":1,"op":1,"ar":1,"sum":"Respondent Hernandez, a prisoner proceeding pro se, filed five civil rights suits in forma pauperis against petitioner California prison officials, alleging, inter alia, that he was drugged and homosexually raped 28 times by various inmates and prison officials at different institutions. Finding that the facts alleged appeared to be wholly fanciful, the District Court dismissed the cases under 28 U. S. C. § 1915(d), …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"4, 5, 22","1":"25, 28","2":"3, 10, 15, 19, 27","3":"12, 22"}},{"t":"case","label":"Edelman v. Lynchburg Coll.","cite":"535 U.S. 106","y":2002,"id":"2001/00-1072","sc":1,"sum":"The Court held that the EEOC's relation-back regulation was an unassailable interpretation of Title VII of the Civil Rights Act of 1964.","sumSrc":"Oyez","by":{"0":"36"}},{"t":"case","label":"Eiber Radiology, Inc. v. Toshiba Am. Med. Sys., Inc.","cite":"673 F. App’x 925","y":2016,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/673/925/","by":{"0":"17"}},{"t":"case","label":"El-Shaddai v. Zamora","cite":"833 F.3d 1036","y":2016,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/833/1036/","sum":"Explaining that a dismissal for failure to exhaust does not count as a strike unless it is made pursuant to Rule 12(b)(6).","sumSrc":"brief:0","by":{"0":"30","3":"17"}},{"t":"case","label":"Escalera v. Samaritan Vill.","cite":"938 F.3d 380","y":2019,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/938/380/","by":{"0":"9"}},{"t":"case","label":"FAA v. Cooper","cite":"566 U.S. 284","y":2012,"id":"2011/10-1024","sc":1,"sum":"The Court held that the Privacy Act of 1974 does not cover mental and emotional distress under \"actual damages.\"","sumSrc":"Oyez","by":{"0":"17","3":"5"}},{"t":"case","label":"Federated Dep’t Stores, Inc. v. Moitie","cite":"452 U.S. 394","y":1981,"id":"1980/79-1517","sc":1,"sum":"Res judicata bars relitigation of the unappealed adverse judgments against respondents as to their federal-law claims. The res judicata consequences of a final, unappealed judgment on the merits are not altered by the fact that the judgment may have been wrong or rested on a legal principle subsequently overruled in another case. There is no general equitable doctrine which countenances an exception to the finality …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"15","3":"6"}},{"t":"case","label":"Fifth Third Bancorp v. Dudenhoeffer","cite":"573 U.S. 409","y":2014,"id":"2013/12-751","sc":1,"sum":"The Court held that a trustee of an employee stock ownership plan is subject to the same duty of prudence as the trustee of a Employee Retirement Income Security Act.","sumSrc":"Oyez","by":{"0":"15"}},{"t":"case","label":"Flagler v. Trainor","cite":"663 F.3d 543","y":2011,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/663/543/","sum":"Explaining that, although claims dismissed based on absolute prosecutorial immunity may sometimes be “considered ‘frivolous’ for purposes of 28 U.S.C. § 1915(g),” that label does not fit claims presenting a “serious” basis for liability.","sumSrc":"brief:0","by":{"0":"42"}},{"t":"case","label":"Fuller v. Sherve","cite":"2014 WL 1347430","y":2014,"court":"W.D. Mich. Apr. 4","by":{"0":"32"}},{"t":"case","label":"Gartrell v. Ashcroft","cite":"191 F. Supp. 2d 23","y":2002,"court":"D.D.C.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/191/23/","by":{"0":"31"}},{"t":"case","label":"Gen. Dynamics Land Sys., Inc. v. Cline","cite":"540 U.S. 581","y":2004,"id":"2003/02-1080","sc":1,"sum":"Justice David H. Souter delivered the Court's 6-3 opinion that the Age Discrimination in Employment Act's \"text, structure, purpose, history, and relationship to other federal statutes show that the statute does not mean to stop an employer from favoring an older employee over a younger one.\" The Court cited a long-held understanding of the \"ADEA as a remedy for unfair preference based on relative youth, leaving complaints of the relatively young outside the statutory concern.\" The Court also noted the findings section of the act included no evidence of younger workers being discriminated against in favor of older workers.","sumSrc":"Oyez","by":{"0":"20"}},{"t":"case","label":"Green v. Young","cite":"454 F.3d 405","y":2006,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/454/405/","by":{"0":"41"}},{"t":"case","label":"Griffin v. Illinois","cite":"351 U.S. 12","y":1956,"id":"1955/95","sc":1,"sum":"In a 5–4 decision authored by Justice Hugo L. Black, the Court reasoned that there is \"no meaningful distinction\" between denying indigent defendants the right to appeal and denying them a trial. Because Illinois conceded that Griffin and Crenshaw could not file for appeal without a transcript, the Court found that their rights to due process and equal protection had been denied.","sumSrc":"Oyez","by":{"0":"37"}},{"t":"case","label":"Gustafson v. Alloyd Co.","cite":"513 U.S. 561","y":1995,"id":"1994/93-404","sc":1,"sum":"Petitioners (collectively Gustafson), the sole shareholders of Alloyd, Inc., sold substantially all of its stock to respondents and other buyers in a private sale agreement. The purchase price included a payment reflecting an estimated increase in the company's net worth from the end of the previous year through the closing, since hard financial data were unavailable. The contract provided that if a year-end audit …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"23"}},{"t":"case","label":"Hampton v. Pac. Inv. Mgmt. Co.","cite":"869 F.3d 844","y":2017,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/869/844/","by":{"0":"17"}},{"t":"case","label":"Heck v. Humphrey","cite":"512 U.S. 477","y":1994,"id":"1993/93-6188","sc":1,"op":2,"ar":17,"sum":"The Supreme Court held that a defendant cannot claim damages for an allegedly unconstitutional conviction or imprisonment without showing that the conviction or sentence has been overturned in some way. The defendant must also exhaust state court remedies before bringing a §1983 action.","sumSrc":"Oyez","by":{"0":"passim","1":"passim","2":"6, 28","3":"3, 18, 22, 23"}},{"t":"case","label":"Holt v. Hobbs","cite":"135 S. Ct. 853","y":2015,"id":"2014/13-6827","sc":1,"op":1,"sum":"The Court held that the Department of Corrections' grooming policy violated an inmate's right to religious exercise.","sumSrc":"Oyez","by":{"0":"39"}},{"t":"case","label":"INS v. St. Cyr","cite":"533 U.S. 289","y":2001,"id":"2000/00-767","sc":1,"sum":"The Court held that habeas jurisdiction was not repealed by AEDPA and IIRIRA.","sumSrc":"Oyez","by":{"0":"41"}},{"t":"case","label":"Johnson v. Williams","cite":"568 U.S. 289","y":2013,"id":"2012/11-465","sc":1,"sum":"The Court found that an entire claim can be \"adjudicated on its merits\" even if the federal law claim was not expressly addressed.","sumSrc":"Oyez","by":{"0":"17"}},{"t":"case","label":"Jones v. Bock","cite":"549 U.S. 199","y":2007,"id":"2006/05-7058","sc":1,"op":2,"ar":1,"sum":"The Court ruled unanimously that the Sixth Circuit's rules for exhaustion of administrative remedies were not required by the Prisoner Litigation Reform Act. The opinion by Chief Justice John Roberts held that prisoners bring civil rights lawsuits do not need to demonstrate that they have already exhausted all administrative remedies.","sumSrc":"Oyez","by":{"0":"19, 29, 40","1":"3, 36, 38","2":"2, 30","3":"8, 20"}},{"t":"case","label":"Jones v. Kirchner","cite":"2008 WL 2202220","y":2008,"court":"D.D.C. May 27","by":{"0":"34"}},{"t":"case","label":"Kamelgard v. Macura","cite":"585 F.3d 334","y":2009,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/585/334/","by":{"0":"17"}},{"t":"case","label":"U.S. ex rel. Karvelas v. MelroseWakefield Hosp.","cite":"360 F.3d 220","y":2004,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/360/220/","by":{"0":"16"}},{"t":"case","label":"Lacey v. Homeowners of Am. Ins. Co.","cite":"546 F. App’x 755","y":2013,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/546/755/","by":{"0":"17"}},{"t":"case","label":"Lagos v. United States","cite":"138 S. Ct. 1684","y":2018,"id":"2017/16-1519","sc":1,"sum":"The Court held that under the Mandatory Victims Restitution Act, pursuant to 18 U.S.C. § 3663A(b)(4), which pertains to reimbursement by defendants to victims for expenses incurred during the investigation or prosecution related to the offense, the words “investigation” and “proceedings” encompass only government investigations and criminal proceedings and do not include private investigations and civil or bankruptcy proceedings.","sumSrc":"Oyez","by":{"0":"23","3":"12"}},{"t":"case","label":"Lewis v. Casey","cite":"518 U.S. 343","y":1996,"id":"1995/94-1511","sc":1,"sum":"The Court held that the success of Casey's systemic challenge was dependent on the ability to show widespread actual injury, and the District Court's failure to identify anything more than isolated instances of actual injury rendered its finding of a systemic Bounds violation invalid.","sumSrc":"Oyez","by":{"0":"38"}},{"t":"case","label":"Little v. Streater","cite":"452 U.S. 1","y":1981,"id":"1980/79-6779","sc":1,"sum":"In the circumstances of this case, application of § 46b-168 to deny appellant blood grouping tests because of his lack of financial resources violated the due process guarantee of the Fourteenth Amendment.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"38"}},{"t":"case","label":"M.L.B. v. S.L.J.","cite":"519 U.S. 102","y":1996,"id":"1996/95-853","sc":1,"sum":"The Court held that, just as a State may not block an indigent petty offender's access to an appeal afforded others, so Mississippi may not deny M.L.B., because of her poverty, appellate review of the sufficiency of the evidence on which the trial court found her unfit to remain a parent. \"We place decrees forever terminating parental rights in the category of cases in which the State may not 'bolt the door to equal justice,'\" wrote Justice Ginsburg, \"recognizing that parental termination decrees are among the most severe forms of state action.\" Chief Justice William H. Rehnquist and Justices Clarence Thomas and Antonin Scalia dissented.","sumSrc":"Oyez","by":{"0":"38","1":"39"}},{"t":"case","label":"Malek v. Reding","cite":"195 F. App’x 714","y":2006,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/195/714/","by":{"0":"30","3":"17"}},{"t":"case","label":"Maracich v. Spears","cite":"570 U.S. 48","y":2013,"id":"2012/12-25","sc":1,"sum":"The Court found that lawyers may use personal information protected by the Driver's Privacy Protection Act to find potential plaintiffs for a group action.","sumSrc":"Oyez","by":{"0":"20"}},{"t":"case","label":"Martin v. D.C. Court of Appeals","cite":"506 U.S. 1","y":1992,"id":"1992/92-5584","sc":1,"op":3,"sum":"Martin is denied leave to proceed informa pauperisin the instant cases, and the Clerk is directed not to accept any further petitions for certiorari from him in noncriminal matters unless he pays the required docketing fee and submits his petition in compliance with this Court's Rule 33. Martin is a notorious abuser of the Court's certiorari process, and consideration of his repetitious and frivolous petitions does …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"39","2":"31"}},{"t":"case","label":"McCarthy v. Madigan","cite":"503 U.S. 140","y":1992,"id":"1991/90-6861","sc":1,"sum":"Exhaustion of the Bureau of Prisons' administrative procedure is not required before a federal prisoner can initiate a Bivens action solely for money damages.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"37"}},{"t":"case","label":"McDonnell v. United States","cite":"136 S. Ct. 2355","y":2016,"id":"2015/15-474","sc":1,"sum":"The Court held that, for the purpose of federal bribery statutes, an “official act” is a decision or action on a question, matter, cause, suit, proceeding, or controversy that involves a specific exercise of formal governmental power.","sumSrc":"Oyez","by":{"0":"21","2":"19"}},{"t":"case","label":"McLean v. United States","cite":"566 F.3d 391","y":2009,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/566/391/","op":1,"sum":"Stating default rule that Rule 12(b)(6) dismissal “is presumed” to be with prejudice “unless otherwise specified” and that it therefore “follows that the type of prior dismissal for failure to state a claim contemplated by § 1915(g) is one” with prejudice.","sumSrc":"brief:1","by":{"0":"16, 18, 23, 28","1":"17, 23, 28","3":"5, 8, 16"}},{"t":"case","label":"Mejia v. Harrington","cite":"541 F. App’x 709","y":2013,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/541/709/","op":1,"sum":"Recognizing that action barred by Heck could not be considered “malicious” or “frivolous” because it had a plausible basis in case law.","sumSrc":"brief:3","by":{"0":"33, 42","3":"23"}},{"t":"case","label":"Millhouse v. Heath","cite":"866 F.3d 152","y":2017,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/866/152/","op":1,"by":{"0":"17, 19","1":"17","3":"7"}},{"t":"case","label":"Morissette v. United States","cite":"342 U.S. 246","y":1952,"id":"scdb/1951-028","sc":1,"sum":"1. A criminal intent is an essential element of an offense under 18 U. S. C. § 641, which provides that \"whoever embezzles, steals, purloins, or knowingly converts\" property -of the United States is punishable by fine and imprisonment.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"17"}},{"t":"case","label":"Neitzke v. Williams","cite":"490 U.S. 319","y":1989,"id":"1988/87-1882","sc":1,"op":1,"sum":"A complaint filed in forma pauperis is not automatically frivolous within the meaning of § 1915(d) because it fails to state a claim under Rule 12(b)(6). The two standards were devised to serve distinctive goals and have separate functions. Under Rule 12(b)(6)'s failure-tostate-a-claim standard-which is designed to streamline litigation by dispensing with needless discovery and factfinding-a court may dismiss a …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"3, 4, 5, 21","1":"passim","2":"passim","3":"10, 14"}},{"t":"case","label":"Nelson v. Citibank Mastercard","cite":"3 F.3d 439","y":1993,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/3/439/","sum":"Holding that an appeal dismissed as premature did not count as a strike because the dismissal “had nothing to do with the merits”.","sumSrc":"brief:0","by":{"0":"17"}},{"t":"case","label":"Orr v. Clements","cite":"688 F.3d 463","y":2012,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/688/463/","op":1,"by":{"0":"35, 36","1":"14, 33","2":"28"}},{"t":"case","label":"Perez v. Sifel","cite":"57 F.3d 503","y":1995,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/57/503/","by":{"0":"33"}},{"t":"case","label":"Pittman v. Moore","cite":"980 F.2d 994","y":1993,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/980/994/","by":{"0":"22","3":"12"}},{"t":"case","label":"Porter v. Nussle","cite":"534 U.S. 516","y":2002,"id":"2001/00-853","sc":1,"sum":"The Court held that the PLRA's exhaustion requirement applies to all inmate suits about prison life, whether they involve general circumstances or particular episodes, and whether they allege excessive force or some other wrong. The Court rejected Nussle's argument that Congress added the words \"prison conditions\" to exempt excessive force claims.","sumSrc":"Oyez","by":{"0":"5","2":"1, 3, 14, 26"}},{"t":"case","label":"Pratt v. Ventas, Inc.","cite":"365 F.3d 514","y":2004,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/365/514/","by":{"0":"17"}},{"t":"case","label":"Price v. Cty. Court Clerk of Hill Cty.","cite":"73 F. App’x 80","y":2003,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/73/80/","by":{"0":"42"}},{"t":"case","label":"Reed v. Sturdivant","cite":"176 F.3d 1051","y":1999,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/176/1051/","by":{"0":"17"}},{"t":"case","label":"Rollins v. Wackenhut Servs., Inc.","cite":"703 F.3d 122","y":2012,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/703/122/","by":{"0":"16"}},{"t":"case","label":"Russello v. United States","cite":"464 U.S. 16","y":1983,"id":"1983/82-472","sc":1,"sum":"The insurance proceeds petitioner received as a result of his arson activities constitute an \"interest\" within the meaning of § 1963(a)(1) and are therefore subject to forfeiture.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"24"}},{"t":"case","label":"Ruth v. Richard","cite":"139 F. App’x 470","y":2005,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/139/470/","by":{"0":"42"}},{"t":"case","label":"Safir v. U.S. Lines, Inc.","cite":"792 F.2d 19","y":1986,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/792/19/","by":{"0":"39"}},{"t":"case","label":"Semtek Int’l Inc. v. Lockheed Martin Corp.","cite":"531 U.S. 497","y":2001,"id":"2000/99-1551","sc":1,"sum":"The Court held that \"[b]ecause the claim-preclusive effect of a federal court's dismissal 'upon the merits' of a diversity action on state statute-of-limitations grounds is governed by a federal rule, which in turn (in diversity cases) incorporates the claim-preclusion law that would be applied by state courts in the State in which the federal court sits, the Maryland Court of Special Appeals erred in holding that the California federal court's dismissal 'upon the merits' necessarily precluded the Maryland state-court action.\" Thus, the District Court's dismissal on the merits of claims as untimely under California law did not preclude Semtek from asserting its claims in a different state court forum.","sumSrc":"Oyez","by":{"0":"1, 10, 16","1":"15","2":"15","3":"1"}},{"t":"case","label":"Smith v. Bennett","cite":"365 U.S. 708","y":1961,"id":"1960/174","sc":1,"sum":"Iowa statutes that require an indigent prisoner of the State to pay a filing fee before his application for a writ of habeas corpus ($4) or the allowance of his appeal ($3) in such proceedings will be docketed in a state court deny him the equal protection of the laws in violation of the Fourteenth Amendment. Burns v. Ohio, 360 U. S. 252. Pp. 708-714. Judgments vacated and causes remanded.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"38"}},{"t":"case","label":"Smith v. Washington","cite":"103 F.3d 133","y":1996,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/103/133/","by":{"0":"42"}},{"t":"case","label":"Snider v. Melindez","cite":"199 F.3d 108","y":1999,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/199/108/","by":{"0":"passim","3":"10, 17"}},{"t":"case","label":"Steele v. Fed. Bureau of Prisons","cite":"355 F.3d 1204","y":2003,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/355/1204/","by":{"0":"30"}},{"t":"case","label":"Tafari v. Hues","cite":"473 F.3d 440","y":2007,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/473/440/","sum":"Holding that an appeal dismissed as premature did not count as a strike because the dismissal “had nothing to do with the merits”.","sumSrc":"brief:0","by":{"0":"26, 34","3":"2"}},{"t":"case","label":"Taylor v. Johnson","cite":"257 F.3d 470","y":2001,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/257/470/","by":{"0":"22"}},{"t":"case","label":"Thomas v. Holder","cite":"750 F.3d 899","y":2014,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/750/899/","by":{"0":"13, 39"}},{"t":"case","label":"Thompson v. Drug Enf’t Admin.","cite":"492 F.3d 428","y":2007,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/492/428/","sum":"Holding that a dismissal for failure to prosecute did not count as a strike because it was “made without regard to the merits of the claim”.","sumSrc":"brief:0","by":{"0":"29, 30"}},{"t":"case","label":"United States v. Jones","cite":"565 U.S. 400","y":2012,"id":"2011/10-1259","sc":1,"sum":"The Court found that a police department's placement of a GPS tracking device on a man's Jeep without his knowledge was an illegal search under the Fourth Amendment.","sumSrc":"Oyez","by":{"0":"34"}},{"t":"case","label":"United States v. Mottaz","cite":"476 U.S. 834","y":1986,"id":"1985/85-546","sc":1,"sum":"Respondent's suit is \"a civil action... to adjudicate a disputed title to real property in which the United States claims an interest,\" within the meaning of the Quiet Title Act, and therefore is barred by that Act's 12-year limitations period.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"11, 24"}},{"t":"case","label":"Warnock v. Pecos Cty.","cite":"88 F.3d 341","y":1996,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/88/341/","by":{"0":"25"}},{"t":"case","label":"Washington v. L.A. Cty. Sheriff’s Dep’t","cite":"833 F.3d 1048","y":2016,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/833/1048/","sum":"Holding that dismissals based on Younger abstention are not strikes.","sumSrc":"brief:0","by":{"0":"25, 33, 42"}},{"t":"case","label":"White v. Colorado","cite":"157 F.3d 1226","y":1998,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/157/1226/","op":1,"ar":3,"by":{"0":"40","2":"32"}},{"t":"case","label":"Wilkinson v. Dotson","cite":"544 U.S. 74","y":2005,"id":"2004/03-287","sc":1,"sum":"Yes and No. In an 8-1 decision, the Court affirmed the appellate court and ruled that prisoners could use Section 1983 to challenge a state's parole procedures.","sumSrc":"Oyez","by":{"0":"33"}},{"t":"case","label":"Wolff v. McDonnell","cite":"418 U.S. 539","y":1974,"id":"1973/73-679","sc":1,"sum":"The Supreme Court held that while prisoners are not entitled to full due process protections, disciplinary proceedings must include written notice to the defendant of the charges, a written statement of evidence, and the opportunity for an inmate to call witnesses and present evidence.","sumSrc":"Oyez","by":{"0":"37, 41"}},{"t":"case","label":"Woodford v. Ngo","cite":"548 U.S. 81","y":2006,"id":"2005/05-416","sc":1,"ar":2,"sum":"In a 6-to-3 decision authored by Justice Samuel Alito, the Supreme Court held that a prisoner must properly exhaust any available administrative remedies before bringing suit in federal court. This understanding of the PLRA's exhaustion provision mirrors that of the traditional exhaustion provision in administrative law and is \"substantively similar\" to that of habeas corpus law.","sumSrc":"Oyez","by":{"0":"5","1":"2, 38","2":"1, 3, 14, 30","3":"8, 19"}},{"t":"case","label":"Yates v. United States","cite":"135 S. Ct. 1074","y":2015,"id":"2014/13-7451","sc":1,"sum":"The Court ruled that a “tangible item” as defined by Section 1519 of the Sarbanes-Oxley Act is one used to record or preserve information.","sumSrc":"Oyez","by":{"0":"22","3":"15"}},{"t":"case","label":"Zadvydas v. Davis","cite":"533 U.S. 678","y":2001,"id":"2000/99-7791","sc":1,"sum":"The Court held that \"the statute, read in light of the Constitution's demands, limits an alien's post-removal-period detention to a period reasonably necessary to bring about that alien's removal from the United States\" and \"does not permit indefinite detention.\" \"Based on our conclusion that indefinite detention of aliens in the former category would raise serious constitutional concerns, we construe the statute to contain an implicit 'reasonable time' limitation, the application of which is subject to federal court review,\" wrote Justice Breyer.","sumSrc":"Oyez","by":{"0":"37"}},{"t":"case","label":"Wayne A. Kalkwarf, Petitions to Proceed In Forma Pauperis: The Effect of In re McDonald and Neitzke v. Williams","cite":"24 Creighton L. Rev. 803","y":1991,"url":"https://www.courtlistener.com/c/Creighton%20L.%20Rev./24/803/","op":1,"by":{"0":"3"}},{"t":"case","label":"Bragdon v. Abbott","cite":"524 U.S. 624","y":1998,"id":"1997/97-156","sc":1,"sum":"In a 5-to-4 opinion, the Court held that although the ADA does not force care-givers to treat an \"individual [who] poses a direct threat to the health or safety of others,\" it also prohibits discrimination against any individual \"on the basis of disability in the enjoyment of the services of any place of public accommodation by any person who operates [such] a place.\" The Court then reasoned that since HIV \"substantially limits\" major life activities, such as reproduction, the infection is a \"disability\" that entitles its victims to ADA protections.","sumSrc":"Oyez","by":{"1":"18"}},{"t":"case","label":"Brown v. Secretary Pennsylvania Department of Corrections","cite":"486 F. App’x 299","y":2012,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/486/299/","op":1,"by":{"1":"35"}},{"t":"case","label":"Childs v. Miller","cite":"713 F.3d 1262","y":2013,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/713/1262/","op":1,"by":{"1":"7","2":"8"}},{"t":"case","label":"Cochise Consultancy, Inc. v. United States ex rel. Hunt","cite":"139 S. Ct. 1507","y":2019,"id":"2018/18-315","sc":1,"op":1,"ar":1,"sum":"The limitations period in 31 U. S. C. §3731(b)(2)—which provides that a False Claims Act action must be brought within 3 years after the “the official of the United States charged with responsibility to act in the circumstances” knew or should have known the relevant facts, but not more than 10 years after the violation—applies in a qui tam suit in which the Federal Government has declined to intervene; the relator in a nonintervened suit is not “the official of the United States” whose knowledge triggers §3731(b)(2)’s limitations period.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"24","2":"21"}},{"t":"case","label":"Cohen v. Corrections Corp. of America","cite":"439 F. App’x 489","y":2011,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/439/489/","by":{"1":"19, 21","3":"11"}},{"t":"case","label":"Colby v. Herrick","cite":"849 F.3d 1273","y":2017,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/849/1273/","by":{"1":"36"}},{"t":"case","label":"Daker v. Jackson","cite":"942 F.3d 1252","y":2019,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/942/1252/","by":{"1":"39","3":"21"}},{"t":"case","label":"De La Garza v. De La Garza","cite":"91 F. App’x 508","y":2004,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/91/508/","by":{"1":"19"}},{"t":"case","label":"Jackson v. Florida Dep’t of Fin. Servs.","cite":"479 F. App’x 289","y":2012,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/479/289/","op":2,"by":{"1":"20, 21","3":"12"}},{"t":"case","label":"Johnson v. Edlow","cite":"37 F. Supp. 2d 775","y":1999,"court":"E.D. Va.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/37/775/","by":{"1":"2, 20, 21"}},{"t":"case","label":"Kennedy v. Getz","cite":"757 F. App’x 205","y":2018,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/757/205/","sum":"Noting that the district court instructed the prisoner to “seek leave to amend his [earlier-filed] complaint”.","sumSrc":"brief:1","by":{"1":"19, 20","3":"11, 12"}},{"t":"case","label":"Lamar, Archer & Cofrin, LLP v. Appling","cite":"138 S. Ct. 1752","y":2018,"id":"2017/16-1215","sc":1,"sum":"The Court decided that a statement regarding a specific asset can be a “statement respecting the debtor’s . . . financial condition” under section 523(a)(2)(B) of the Bankruptcy Code.","sumSrc":"Oyez","by":{"1":"18"}},{"t":"case","label":"Lewis v. Sullivan","cite":"279 F.3d 526","y":2002,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/279/526/","by":{"1":"39, 40","2":"32"}},{"t":"case","label":"New Prime Inc. v. Oliveira","cite":"139 S. Ct. 532","y":2019,"id":"2018/17-340","sc":1,"sum":"A court should determine whether the Federal Arbitration Act’s §1 exclusion for disputes involving the “contracts of employment” of certain transportation workers applies before ordering arbitration; here, truck driver Oliveira’s independent contractor operating agreement with New Prime falls within that exception.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"12"}},{"t":"case","label":"O’Connor v. Backman","cite":"743 F. App’x 373","y":2018,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/743/373/","by":{"1":"35"}},{"t":"case","label":"O’Neal v. Price","cite":"531 F.3d 1146","y":2008,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/531/1146/","op":1,"by":{"1":"14"}},{"t":"case","label":"Oncale v. Sundowner Offshore Servs., Inc.","cite":"523 U.S. 75","y":1998,"id":"1997/96-568","sc":1,"sum":"The Court held that while Title VII does not prohibit all verbal or physical harassment in the workplace, it does bar all forms of discrimination \"because of\" sex. Such discrimination, whether motivated by sexual desire or not, is actionable so long at it places its victim in an objectively disadvantageous working condition, regardless of the victim's gender.","sumSrc":"Oyez","by":{"1":"14"}},{"t":"case","label":"Paganis v. Blonstein","cite":"3 F.3d 1067","y":1993,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/3/1067/","sum":"Holding “Rule 41(b) states that unless the judgment provides otherwise, involuntary dismissal, including a dismissal for failure to state a claim under Rule 12(b)(6), is an adjudication on the merits—in other words, a dismissal with prejudice”.","sumSrc":"brief:1","by":{"1":"16"}},{"t":"case","label":"Paul v. Marberry","cite":"658 F.3d 702","y":2011,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/658/702/","op":1,"by":{"1":"14"}},{"t":"case","label":"Reno v. Bossier Parish School Bd.","cite":"528 U.S. 320","y":2000,"id":"1998/98-405","sc":1,"sum":"The Court held that section 5 does not prohibit preclearance of a redistricting plan enacted with a discriminatory but nonretrogressive purpose. \"As we have repeatedly noted, in vote-dilution cases [section 5] prevents nothing but backsliding, and preclearance under [section 5] affirms nothing but the absence of backsliding,\" wrote Justice Scalia.","sumSrc":"Oyez","by":{"1":"24"}},{"t":"case","label":"Sekhar v. United States","cite":"570 U.S. 729","y":2013,"id":"2012/12-357","sc":1,"sum":"The Court held that attempting to compel a person to issue a recommendation does not constitute extortion under the Hobbs Act.","sumSrc":"Oyez","by":{"1":"15","2":"16","3":"4"}},{"t":"case","label":"United States v. Williams","cite":"553 U.S. 285","y":2008,"id":"2007/06-694","sc":1,"sum":"Held that the statute was not overly broad as written. Justice Scalia noted specifically that offers to engage in illegal transactions are categorically excluded from First Amendment protection, and he characterized the speech of an individual claiming to be in possession of child pornography in this category of unprotected speech.","sumSrc":"Oyez","by":{"1":"18"}},{"t":"case","label":"United States v. Woods","cite":"571 U.S. 31","y":2013,"id":"2013/12-562","sc":1,"sum":"The Court held that, under the Tax Equity and Fiscal Responsibility Act of 1982, a court in partnership-level proceedings has the right to consider the applicability of any penalty that relates to the partnership.","sumSrc":"Oyez","by":{"1":"29"}},{"t":"case","label":"Wallace v. Baldwin","cite":"895 F.3d 481","y":2018,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/895/481/","by":{"1":"35"}},{"t":"case","label":"Williams v. Paramo","cite":"695 F. App’x 200","y":2017,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/695/200/","by":{"1":"35"}},{"t":"usc","label":"21 U.S.C. § 355","url":"https://www.law.cornell.edu/uscode/text/21/355","subs":["(c)(3)(D)(i)(II)","(q)(2)(B)"],"by":{"1":"9, 12, 27, 27"}},{"t":"usc","label":"28 U.S.C. § 1915","url":"https://www.law.cornell.edu/uscode/text/28/1915","subs":["(b)","(d)","(e)","(e)(2)(B)","(e)(2)(B)(ii)","(g)","(e)(2)","(e)(2)(B)(i)","(e)(2)(B)(iii)"],"stext":{"head":"§1915. Proceedings in forma pauperis","paras":[[0,"(a)(1) Subject to subsection (b), any court of the United States may authorize the commencement, prosecution or defense of any suit, action or proceeding, civil or criminal, or appeal therein, without prepayment of fees or security therefor, by a person who submits an affidavit that includes a statement of all assets such prisoner possesses that the person is unable to pay such fees or give security therefor. Such affidavit shall state the nature of the action, defense or appeal and affiant's belief that the person is entitled to redress."],[0,"(2) A prisoner seeking to bring a civil action or appeal a judgment in a civil action or proceeding without prepayment of fees or security therefor, in addition to filing the affidavit filed under paragraph (1), shall submit a certified copy of the trust fund account statement (or institutional equivalent) for the prisoner for the 6-month period immediately preceding the filing of the complaint or notice of appeal, obtained from the appropriate official of each prison at which the prisoner is or was confined."],[0,"(3) An appeal may not be taken in forma pauperis if the trial court certifies in writing that it is not taken in good faith."],[0,"(b)(1) Notwithstanding subsection (a), if a prisoner brings a civil action or files an appeal in forma pauperis, the prisoner shall be required to pay the full amount of a filing fee. The court shall assess and, when funds exist, collect, as a partial payment of any court fees required by law, an initial partial filing fee of 20 percent of the greater of—"],[1,"(A) the average monthly deposits to the prisoner's account; or"],[1,"(B) the average monthly balance in the prisoner's account for the 6-month period immediately preceding the filing of the complaint or notice of appeal."],[0,"(2) After payment of the initial partial filing fee, the prisoner shall be required to make monthly payments of 20 percent of the preceding month's income credited to the prisoner's account. The agency having custody of the prisoner shall forward payments from the prisoner's account to the clerk of the court each time the amount in the account exceeds $10 until the filing fees are paid."],[0,"(3) In no event shall the filing fee collected exceed the amount of fees permitted by statute for the commencement of a civil action or an appeal of a civil action or criminal judgment."],[0,"(4) In no event shall a prisoner be prohibited from bringing a civil action or appealing a civil or criminal judgment for the reason that the prisoner has no assets and no means by which to pay the initial partial filing fee."],[0,"(c) Upon the filing of an affidavit in accordance with subsections (a) and (b) and the prepayment of any partial filing fee as may be required under subsection (b), the court may direct payment by the United States of the expenses of (1) printing the record on appeal in any civil or criminal case, if such printing is required by the appellate court; (2) preparing a transcript of proceedings before a United States magistrate judge in any civil or criminal case, if such transcript is required by the district court, in the case of proceedings conducted under section 636(b) of this title or under section 3401(b) of title 18, United States Code; and (3) printing the record on appeal if such printing is required by the appellate court, in the case of proceedings conducted pursuant to section 636(c) of this title. Such expenses shall be paid when authorized by the Director of the Administrative Office of the United States Courts."],[0,"(d) The officers of the court shall issue and serve all process, and perform all duties in such cases. Witnesses shall attend as in other cases, and the same remedies shall be available as are provided for by law in other cases."],[0,"(e)(1) The court may request an attorney to represent any person unable to afford counsel."],[0,"(2) Notwithstanding any filing fee, or any portion thereof, that may have been paid, the court shall dismiss the case at any time if the court determines that—"],[1,"(A) the allegation of poverty is untrue; or"],[1,"(B) the action or appeal—"],[2,"(i) is frivolous or malicious;"],[2,"(ii) fails to state a claim on which relief may be granted; or"],[2,"(iii) seeks monetary relief against a defendant who is immune from such relief."],[0,"(f)(1) Judgment may be rendered for costs at the conclusion of the suit or action as in other proceedings, but the United States shall not be liable for any of the costs thus incurred. If the United States has paid the cost of a stenographic transcript or printed record for the prevailing party, the same shall be taxed in favor of the United States."],[0,"(2)(A) If the judgment against a prisoner includes the payment of costs under this subsection, the prisoner shall be required to pay the full amount of the costs ordered."],[0,"(B) The prisoner shall be required to make payments for costs under this subsection in the same manner as is provided for filing fees under subsection (a)(2)."],[0,"(C) In no event shall the costs collected exceed the amount of the costs ordered by the court."],[0,"(g) In no event shall a prisoner bring a civil action or appeal a judgment in a civil action or proceeding under this section if the prisoner has, on 3 or more prior occasions, while incarcerated or detained in any facility, brought an action or appeal in a court of the United States that was dismissed on the grounds that it is frivolous, malicious, or fails to state a claim upon which relief may be granted, unless the prisoner is under imminent danger of serious physical injury."],[0,"(h) As used in this section, the term \"prisoner\" means any person incarcerated or detained in any facility who is accused of, convicted of, sentenced for, or adjudicated delinquent for, violations of criminal law or the terms and conditions of parole, probation, pretrial release, or diversionary program."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1915?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§1915. Proceedings in forma pauperis","tname":"Judiciary and Judicial Procedure","by":{"1":"5, 5, 18, 30, 4, 22, passim","2":"2, 4, 23, 24, 4, 2, 21, 24, 4, 22, 5, 21, 4, 5, 21, 4, passim","3":"13, 14, passim"}},{"t":"usc","label":"28 U.S.C. § 1915A","url":"https://www.law.cornell.edu/uscode/text/28/1915A","subs":["(a)","(b)","(b)(1)"],"stext":{"head":"§1915A. Screening","paras":[[0,"(a) Screening.—The court shall review, before docketing, if feasible or, in any event, as soon as practicable after docketing, a complaint in a civil action in which a prisoner seeks redress from a governmental entity or officer or employee of a governmental entity."],[0,"(b) Grounds for Dismissal.—On review, the court shall identify cognizable claims or dismiss the complaint, or any portion of the complaint, if the complaint—"],[1,"(1) is frivolous, malicious, or fails to state a claim upon which relief may be granted; or"],[1,"(2) seeks monetary relief from a defendant who is immune from such relief."],[0,"(c) Definition.—As used in this section, the term \"prisoner\" means any person incarcerated or detained in any facility who is accused of, convicted of, sentenced for, or adjudicated delinquent for, violations of criminal law or the terms and conditions of parole, probation, pretrial release, or diversionary program."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1915A?type=usc&year=mostrecent&link-type=html"},"head":"§1915A. Screening","tname":"Judiciary and Judicial Procedure","by":{"1":"30, 4, 4, 11, 22","2":"21, 4, 21, 25, 4, 22, 25, 5","3":"13, 14"}},{"t":"usc","label":"28 U.S.C. § 2074","url":"https://www.law.cornell.edu/uscode/text/28/2074","subs":["(a)"],"by":{"1":"16"}},{"t":"usc","label":"29 U.S.C. § 1342","url":"https://www.law.cornell.edu/uscode/text/29/1342","subs":["(d)(1)(A)"],"by":{"1":"9, 12, 26"}},{"t":"usc","label":"29 U.S.C. § 216","url":"https://www.law.cornell.edu/uscode/text/29/216","subs":["(c)"],"stext":{"head":"§216. Penalties","paras":[[0,"(a) Fines and imprisonment"],[0,"Any person who willfully violates any of the provisions of section 215 of this title shall upon conviction thereof be subject to a fine of not more than $10,000, or to imprisonment for not more than six months, or both. No person shall be imprisoned under this subsection except for an offense committed after the conviction of such person for a prior offense under this subsection."],[0,"(b) Damages; right of action; attorney's fees and costs; termination of right of action"],[0,"Any employer who violates the provisions of section 206 or section 207 of this title shall be liable to the employee or employees affected in the amount of their unpaid minimum wages, or their unpaid overtime compensation, as the case may be, and in an additional equal amount as liquidated damages. Any employer who violates the provisions of section 215(a)(3) or 218d of this title shall be liable for such legal or equitable relief as may be appropriate to effectuate the purposes of section 215(a)(3) or 218d of this title, including without limitation employment, reinstatement, promotion, and the payment of wages lost and an additional equal amount as liquidated damages. Any employer who violates section 203(m)(2)(B) of this title shall be liable to the employee or employees affected in the amount of the sum of any tip credit taken by the employer and all such tips unlawfully kept by the employer, and in an additional equal amount as liquidated damages. An action to recover the liability prescribed in the preceding sentences may be maintained against any employer (including a public agency) in any Federal or State court of competent jurisdiction by any one or more employees for and in behalf of himself or themselves and other employees similarly situated. No employee shall be a party plaintiff to any such action unless he gives his consent in writing to become such a party and such consent is filed in the court in which such action is brought. The court in such action shall, in addition to any judgment awarded to the plaintiff or plaintiffs, allow a reasonable attorney's fee to be paid by the defendant, and costs of the action. The right provided by this subsection to bring an action by or on behalf of any employee, and the right of any employee to become a party plaintiff to any such action, shall terminate upon the filing of a complaint by the Secretary of Labor in an action under section 217 of this title in which (1) restraint is sought of any further delay in the payment of unpaid minimum wages, or the amount of unpaid overtime compensation, as the case may be, owing to such employee under section 206 or section 207 of this title by an employer liable therefor under the provisions of this subsection or (2) legal or equitable relief is sought as a result of alleged violations of section 215(a)(3) or 218d of this title."],[0,"(c) Payment of wages and compensation; waiver of claims; actions by the Secretary; limitation of actions"],[0,"The Secretary is authorized to supervise the payment of the unpaid minimum wages or the unpaid overtime compensation owing to any employee or employees under section 206 or section 207 of this title, and the agreement of any employee to accept such payment shall upon payment in full constitute a waiver by such employee of any right he may have under subsection (b) of this section to such unpaid minimum wages or unpaid overtime compensation and an additional equal amount as liquidated damages. The Secretary may bring an action in any court of competent jurisdiction to recover the amount of unpaid minimum wages or overtime compensation and an equal amount as liquidated damages. The right provided by subsection (b) to bring an action by or on behalf of any employee to recover the liability specified in the first sentence of such subsection and of any employee to become a party plaintiff to any such action shall terminate upon the filing of a complaint by the Secretary in an action under this subsection in which a recovery is sought of unpaid minimum wages or unpaid overtime compensation under sections 206 and 207 of this title or liquidated or other damages provided by this subsection owing to such employee by an employer liable under the provisions of subsection (b), unless such action is dismissed without prejudice on motion of the Secretary. Any sums thus recovered by the Secretary of Labor on behalf of an employee pursuant to this subsection shall be held in a special deposit account and shall be paid, on order of the Secretary of Labor, directly to the employee or employees affected. Any such sums not paid to an employee because of inability to do so within a period of three years shall be covered into the Treasury of the United States as miscellaneous receipts. In determining when an action is commenced by the Secretary of Labor under this subsection for the purposes of the statutes of limitations provided in section 6(a) of the Portal-to-Portal Act of 1947 [29 U.S.C. 255(a)], it shall be considered to be commenced in the case of any individual claimant on the date when the complaint is filed if he is specifically named as a party plaintiff in the complaint, or if his name did not so appear, on the subsequent date on which his name is added as a party plaintiff in such action. The authority and requirements described in this subsection shall apply with respect to a violation of section 203(m)(2)(B) of this title, as appropriate, and the employer shall be liable for the amount of the sum of any tip credit taken by the employer and all such tips unlawfully kept by the employer, and an additional equal amount as liquidated damages."],[0,"(d) Savings provisions"],[0,"In any action or proceeding commenced prior to, on, or after August 8, 1956, no employer shall be subject to any liability or punishment under this chapter or the Portal-to-Portal Act of 1947 [29 U.S.C. 251 et seq.] on account of his failure to comply with any provision or provisions of this chapter or such Act (1) with respect to work heretofore or hereafter performed in a workplace to which the exemption in section 213(f) of this title is applicable, (2) with respect to work performed in Guam, the Canal Zone or Wake Island before the effective date of this amendment of subsection (d), or (3) with respect to work performed in a possession named in section 206(a)(3) 1 of this title at any time prior to the establishment by the Secretary, as provided therein, of a minimum wage rate applicable to such work."],[0,"(e) Civil penalties for certain violations"],[0,"(1)(A) Any person who violates the provisions of sections 2 212 or 213(c) of this title, relating to child labor, or any regulation issued pursuant to such sections, shall be subject to a civil penalty not to exceed—"],[1,"(i) $11,000 for each employee who was the subject of such a violation; or"],[1,"(ii) $50,000 with regard to each such violation that causes the death or serious injury of any employee under the age of 18 years, which penalty may be doubled where the violation is a repeated or willful violation."],[0,"(B) For purposes of subparagraph (A), the term \"serious injury\" means—"],[1,"(i) permanent loss or substantial impairment of one of the senses (sight, hearing, taste, smell, tactile sensation);"],[1,"(ii) permanent loss or substantial impairment of the function of a bodily member, organ, or mental faculty, including the loss of all or part of an arm, leg, foot, hand or other body part; or"],[1,"(iii) permanent paralysis or substantial impairment that causes loss of movement or mobility of an arm, leg, foot, hand or other body part."],[0,"(2) Any person who repeatedly or willfully violates section 206 or 207 of this title, relating to wages, shall be subject to a civil penalty not to exceed $1,100 for each such violation. Any person who violates section 203(m)(2)(B) of this title shall be subject to a civil penalty not to exceed $1,100 for each such violation, as the Secretary determines appropriate, in addition to being liable to the employee or employees affected for all tips unlawfully kept, and an additional equal amount as liquidated damages, as described in subsection (b)."],[0,"(3) In determining the amount of any penalty under this subsection, the appropriateness of such penalty to the size of the business of the person charged and the gravity of the violation shall be considered. The amount of any penalty under this subsection, when finally determined, may be—"],[1,"(A) deducted from any sums owing by the United States to the person charged;"],[1,"(B) recovered in a civil action brought by the Secretary in any court of competent jurisdiction, in which litigation the Secretary shall be represented by the Solicitor of Labor; or"],[1,"(C) ordered by the court, in an action brought for a violation of section 215(a)(4) of this title or a repeated or willful violation of section 215(a)(2) of this title, to be paid to the Secretary."],[0,"(4) Any administrative determination by the Secretary of the amount of any penalty under this subsection shall be final, unless within 15 days after receipt of notice thereof by certified mail the person charged with the violation takes exception to the determination that the violations for which the penalty is imposed occurred, in which event final determination of the penalty shall be made in an administrative proceeding after opportunity for hearing in accordance with section 554 of title 5 and regulations to be promulgated by the Secretary."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/216?type=usc&year=mostrecent&link-type=html"},"head":"§216. Penalties","tname":"Labor","by":{"1":"9, 12, 27","2":"13"}},{"t":"usc","label":"29 U.S.C. § 2617","url":"https://www.law.cornell.edu/uscode/text/29/2617","subs":["(a)(4)"],"by":{"1":"9, 12, 26"}},{"t":"usc","label":"35 U.S.C. § 271","url":"https://www.law.cornell.edu/uscode/text/35/271","subs":["(e)(6)(A)(ii)(II)"],"by":{"1":"9, 12, 27"}},{"t":"usc","label":"42 U.S.C. § 1983","url":"https://www.law.cornell.edu/uscode/text/42/1983","stext":{"head":"§1983. Civil action for deprivation of rights","paras":[[0,"Every person who, under color of any statute, ordinance, regulation, custom, or usage, of any State or Territory or the District of Columbia, subjects, or causes to be subjected, any citizen of the United States or other person within the jurisdiction thereof to the deprivation of any rights, privileges, or immunities secured by the Constitution and laws, shall be liable to the party injured in an action at law, suit in equity, or other proper proceeding for redress, except that in any action brought against a judicial officer for an act or omission taken in such officer's judicial capacity, injunctive relief shall not be granted unless a declaratory decree was violated or declaratory relief was unavailable. For the purposes of this section, any Act of Congress applicable exclusively to the District of Columbia shall be considered to be a statute of the District of Columbia."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/1983?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1983. Civil action for deprivation of rights","tname":"The Public Health and Welfare","by":{"1":"5","2":"6"}},{"t":"usc","label":"42 U.S.C. § 1997e","url":"https://www.law.cornell.edu/uscode/text/42/1997e","subs":["(a)","(c)(1)","(c)(2)","(c)"],"stext":{"head":"§1997e. Suits by prisoners","paras":[[0,"(a) Applicability of administrative remedies"],[0,"No action shall be brought with respect to prison conditions under section 1983 of this title, or any other Federal law, by a prisoner confined in any jail, prison, or other correctional facility until such administrative remedies as are available are exhausted."],[0,"(b) Failure of State to adopt or adhere to administrative grievance procedure"],[0,"The failure of a State to adopt or adhere to an administrative grievance procedure shall not constitute the basis for an action under section 1997a or 1997c of this title."],[0,"(c) Dismissal"],[0,"(1) The court shall on its own motion or on the motion of a party dismiss any action brought with respect to prison conditions under section 1983 of this title, or any other Federal law, by a prisoner confined in any jail, prison, or other correctional facility if the court is satisfied that the action is frivolous, malicious, fails to state a claim upon which relief can be granted, or seeks monetary relief from a defendant who is immune from such relief."],[0,"(2) In the event that a claim is, on its face, frivolous, malicious, fails to state a claim upon which relief can be granted, or seeks monetary relief from a defendant who is immune from such relief, the court may dismiss the underlying claim without first requiring the exhaustion of administrative remedies."],[0,"(d) Attorney's fees"],[0,"(1) In any action brought by a prisoner who is confined to any jail, prison, or other correctional facility, in which attorney's fees are authorized under section 1988 1 of this title, such fees shall not be awarded, except to the extent that—"],[1,"(A) the fee was directly and reasonably incurred in proving an actual violation of the plaintiff's rights protected by a statute pursuant to which a fee may be awarded under section 1988 1 of this title; and"],[1,"(B)(i) the amount of the fee is proportionately related to the court ordered relief for the violation; or"],[1,"(ii) the fee was directly and reasonably incurred in enforcing the relief ordered for the violation."],[0,"(2) Whenever a monetary judgment is awarded in an action described in paragraph (1), a portion of the judgment (not to exceed 25 percent) shall be applied to satisfy the amount of attorney's fees awarded against the defendant. If the award of attorney's fees is not greater than 150 percent of the judgment, the excess shall be paid by the defendant."],[0,"(3) No award of attorney's fees in an action described in paragraph (1) shall be based on an hourly rate greater than 150 percent of the hourly rate established under section 3006A of title 18 for payment of court-appointed counsel."],[0,"(4) Nothing in this subsection shall prohibit a prisoner from entering into an agreement to pay an attorney's fee in an amount greater than the amount authorized under this subsection, if the fee is paid by the individual rather than by the defendant pursuant to section 1988 1 of this title."],[0,"(e) Limitation on recovery"],[0,"No Federal civil action may be brought by a prisoner confined in a jail, prison, or other correctional facility, for mental or emotional injury suffered while in custody without a prior showing of physical injury or the commission of a sexual act (as defined in section 2246 of title 18)."],[0,"(f) Hearings"],[0,"(1) To the extent practicable, in any action brought with respect to prison conditions in Federal court pursuant to section 1983 of this title, or any other Federal law, by a prisoner confined in any jail, prison, or other correctional facility, pretrial proceedings in which the prisoner's participation is required or permitted shall be conducted by telephone, video conference, or other telecommunications technology without removing the prisoner from the facility in which the prisoner is confined."],[0,"(2) Subject to the agreement of the official of the Federal, State, or local unit of government with custody over the prisoner, hearings may be conducted at the facility in which the prisoner is confined. To the extent practicable, the court shall allow counsel to participate by telephone, video conference, or other communications technology in any hearing held at the facility."],[0,"(g) Waiver of reply"],[0,"(1) Any defendant may waive the right to reply to any action brought by a prisoner confined in any jail, prison, or other correctional facility under section 1983 of this title or any other Federal law. Notwithstanding any other law or rule of procedure, such waiver shall not constitute an admission of the allegations contained in the complaint. No relief shall be granted to the plaintiff unless a reply has been filed."],[0,"(2) The court may require any defendant to reply to a complaint brought under this section if it finds that the plaintiff has a reasonable opportunity to prevail on the merits."],[0,"(h) \"Prisoner\" defined"],[0,"As used in this section, the term \"prisoner\" means any person incarcerated or detained in any facility who is accused of, convicted of, sentenced for, or adjudicated delinquent for, violations of criminal law or the terms and conditions of parole, probation, pretrial release, or diversionary program."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/1997e?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1997e. Suits by prisoners","tname":"The Public Health and Welfare","by":{"1":"30, 5, 11, 22, 23","2":"4, 22, 5, 22, 5, 22","3":"13, 14"}},{"t":"usc","label":"42 U.S.C. § 262","url":"https://www.law.cornell.edu/uscode/text/42/262","subs":["(k)(6)(B)(ii)"],"stext":{"head":"§262. Regulation of biological products","paras":[[0,"(a) Biologics license"],[0,"(1) No person shall introduce or deliver for introduction into interstate commerce any biological product unless—"],[1,"(A) a biologics license under this subsection or subsection (k) is in effect for the biological product; and"],[1,"(B) each package of the biological product is plainly marked with—"],[2,"(i) the proper name of the biological product contained in the package;"],[2,"(ii) the name, address, and applicable license number of the manufacturer of the biological product; and"],[2,"(iii) the expiration date of the biological product."],[0,"(2)(A) The Secretary shall establish, by regulation, requirements for the approval, suspension, and revocation of biologics licenses."],[0,"(B) Pediatric studies.—A person that submits an application for a license under this paragraph shall submit to the Secretary as part of the application any assessments required under section 505B of the Federal Food, Drug, and Cosmetic Act [21 U.S.C. 355c]."],[0,"(C) The Secretary shall approve a biologics license application—"],[1,"(i) on the basis of a demonstration that—"],[2,"(I) the biological product that is the subject of the application is safe, pure, and potent; and"],[2,"(II) the facility in which the biological product is manufactured, processed, packed, or held meets standards designed to assure that the biological product continues to be safe, pure, and potent; and"],[1,"(ii) if the applicant (or other appropriate person) consents to the inspection of the facility that is the subject of the application, in accordance with subsection (c)."],[0,"(D) Postmarket studies and clinical trials; labeling; risk evaluation and mitigation strategy.—A person that submits an application for a license under this paragraph is subject to sections 505(o), 505(p), and 505–1 of the Federal Food, Drug, and Cosmetic Act [21 U.S.C. 355(o), (p), 355–1]."],[0,"(E)(i) The Secretary may rely upon qualified data summaries to support the approval of a supplemental application, with respect to a qualified indication for a drug, submitted under this subsection, if such supplemental application complies with the requirements of subparagraph (B) of section 505(c)(5) of the Federal Food, Drug, and Cosmetic Act [21 U.S.C. 355(c)(5)]."],[0,"(ii) In this subparagraph, the terms \"qualified indication\" and \"qualified data summary\" have the meanings given such terms in section 505(c)(5) of the Federal Food, Drug, and Cosmetic Act."],[0,"(3) The Secretary shall prescribe requirements under which a biological product undergoing investigation shall be exempt from the requirements of paragraph (1)."],[0,"(b) Falsely labeling or marking package or container; altering label or mark"],[0,"No person shall falsely label or mark any package or container of any biological product or alter any label or mark on the package or container of the biological product so as to falsify the label or mark."],[0,"(c) Inspection of establishment for propagation and preparation"],[0,"Any officer, agent, or employee of the Department of Health and Human Services, authorized by the Secretary for the purpose, may during all reasonable hours enter and inspect any establishment for the propagation or manufacture and preparation of any biological product."],[0,"(d) Recall of product presenting imminent hazard; violations"],[0,"(1) Upon a determination that a batch, lot, or other quantity of a product licensed under this section presents an imminent or substantial hazard to the public health, the Secretary shall issue an order immediately ordering the recall of such batch, lot, or other quantity of such product. An order under this paragraph shall be issued in accordance with section 554 of title 5."],[0,"(2) Any violation of paragraph (1) shall subject the violator to a civil penalty of up to $100,000 per day of violation. The amount of a civil penalty under this paragraph shall, effective December 1 of each year beginning 1 year after the effective date of this paragraph, be increased by the percent change in the Consumer Price Index for the base quarter of such year over the Consumer Price Index for the base quarter of the preceding year, adjusted to the nearest 1/10 of 1 percent. For purposes of this paragraph, the term \"base quarter\", as used with respect to a year, means the calendar quarter ending on September 30 of such year and the price index for a base quarter is the arithmetical mean of such index for the 3 months comprising such quarter."],[0,"(e) Interference with officers"],[0,"No person shall interfere with any officer, agent, or employee of the Service in the performance of any duty imposed upon him by this section or by regulations made by authority thereof."],[0,"(f) Penalties for offenses"],[0,"Any person who shall violate, or aid or abet in violating, any of the provisions of this section shall be punished upon conviction by a fine not exceeding $500 or by imprisonment not exceeding one year, or by both such fine and imprisonment, in the discretion of the court."],[0,"(g) Construction with other laws"],[0,"Nothing contained in this chapter shall be construed as in any way affecting, modifying, repealing, or superseding the provisions of the Federal Food, Drug, and Cosmetic Act [21 U.S.C. 301 et seq.]."],[0,"(h) Exportation of partially processed biological products"],[0,"A partially processed biological product which—"],[1,"(1) is not in a form applicable to the prevention, treatment, or cure of diseases or injuries of man;"],[1,"(2) is not intended for sale in the United States; and"],[1,"(3) is intended for further manufacture into final dosage form outside the United States,"],[0,"shall be subject to no restriction on the export of the product under this chapter or the Federal Food, Drug, and Cosmetic Act [21 U.S.C. 301 et seq.] if the product is manufactured, processed, packaged, and held in conformity with current good manufacturing practice requirements or meets international manufacturing standards as certified by an international standards organization recognized by the Secretary and meets the requirements of section 801(e)(1) of the Federal Food, Drug, and Cosmetic Act (21 U.S.C. 381(e))."],[0,"(i) \"Biological product\" defined"],[0,"In this section:"],[1,"(1) The term \"biological product\" means a virus, therapeutic serum, toxin, antitoxin, vaccine, blood, blood component or derivative, allergenic product, protein, or analogous product, or arsphenamine or derivative of arsphenamine (or any other trivalent organic arsenic compound), applicable to the prevention, treatment, or cure of a disease or condition of human beings."],[1,"(2) The term \"biosimilar\" or \"biosimilarity\", in reference to a biological product that is the subject of an application under subsection (k), means—"],[2,"(A) that the biological product is highly similar to the reference product notwithstanding minor differences in clinically inactive components; and"],[2,"(B) there are no clinically meaningful differences between the biological product and the reference product in terms of the safety, purity, and potency of the product."],[1,"(3) The term \"interchangeable\" or \"interchangeability\", in reference to a biological product that is shown to meet the standards described in subsection (k)(4), means that the biological product may be substituted for the reference product without the intervention of the health care provider who prescribed the reference product."],[1,"(4) The term \"reference product\" means the single biological product licensed under subsection (a) against which a biological product is evaluated in an application submitted under subsection (k)."],[0,"(j) Application of Federal Food, Drug, and Cosmetic Act"],[0,"The Federal Food, Drug, and Cosmetic Act [21 U.S.C. 301 et seq.], including the requirements under sections 505(o), 505(p), and 505–1 of such Act [21 U.S.C. 355(o), (p), 355–1], applies to a biological product subject to regulation under this section, except that a product for which a license has been approved under subsection (a) shall not be required to have an approved application under section 505 of such Act."],[0,"(k) Licensure of biological products as biosimilar or interchangeable"],[0,"(1) In general"],[1,"Any person may submit an application for licensure of a biological product under this subsection."],[0,"(2) Content"],[0,"(A) In general"],[0,"(i) Required information"],[3,"An application submitted under this subsection shall include information demonstrating that—"],[4,"(I) the biological product is biosimilar to a reference product based upon data derived from—"],[5,"(aa) analytical studies that demonstrate that the biological product is highly similar to the reference product notwithstanding minor differences in clinically inactive components;"],[5,"(bb) an assessment of toxicity (which may rely on, or consist of, a study or studies described in item (aa) or (cc)); and"],[5,"(cc) a clinical study or studies (including the assessment of immunogenicity and pharmacokinetics or pharmacodynamics) that are sufficient to demonstrate safety, purity, and potency in 1 or more appropriate conditions of use for which the reference product is licensed and intended to be used and for which licensure is sought for the biological product;"],[4,"(II) the biological product and reference product utilize the same mechanism or mechanisms of action for the condition or conditions of use prescribed, recommended, or suggested in the proposed labeling, but only to the extent the mechanism or mechanisms of action are known for the reference product;"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/262?type=usc&year=mostrecent&link-type=html"},"head":"§262. Regulation of biological products","tname":"The Public Health and Welfare","by":{"1":"28","3":"16"}},{"t":"usc","label":"42 U.S.C. § 300aa-22","url":"https://www.law.cornell.edu/uscode/text/42/300aa-22","subs":["(d)"],"stext":{"head":"§300aa–22. Standards of responsibility","paras":[[0,"(a) General rule"],[0,"Except as provided in subsections (b), (c), and (e) State law shall apply to a civil action brought for damages for a vaccine-related injury or death."],[0,"(b) Unavoidable adverse side effects; warnings"],[0,"(1) No vaccine manufacturer shall be liable in a civil action for damages arising from a vaccine-related injury or death associated with the administration of a vaccine after October 1, 1988, if the injury or death resulted from side effects that were unavoidable even though the vaccine was properly prepared and was accompanied by proper directions and warnings."],[0,"(2) For purposes of paragraph (1), a vaccine shall be presumed to be accompanied by proper directions and warnings if the vaccine manufacturer shows that it complied in all material respects with all requirements under the Federal Food, Drug, and Cosmetic Act [21 U.S.C. 301 et seq.] and section 262 of this title (including regulations issued under such provisions) applicable to the vaccine and related to vaccine-related injury or death for which the civil action was brought unless the plaintiff shows—"],[1,"(A) that the manufacturer engaged in the conduct set forth in subparagraph (A) or (B) of section 300aa–23(d)(2) of this title, or"],[1,"(B) by clear and convincing evidence that the manufacturer failed to exercise due care notwithstanding its compliance with such Act and section (and regulations issued under such provisions)."],[0,"(c) Direct warnings"],[0,"No vaccine manufacturer shall be liable in a civil action for damages arising from a vaccine-related injury or death associated with the administration of a vaccine after October 1, 1988, solely due to the manufacturer's failure to provide direct warnings to the injured party (or the injured party's legal representative) of the potential dangers resulting from the administration of the vaccine manufactured by the manufacturer."],[0,"(d) Construction"],[0,"The standards of responsibility prescribed by this section are not to be construed as authorizing a person who brought a civil action for damages against a vaccine manufacturer for a vaccine-related injury or death in which damages were denied or which was dismissed with prejudice to bring a new civil action against such manufacturer for such injury or death."],[0,"(e) Preemption"],[0,"No State may establish or enforce a law which prohibits an individual from bringing a civil action against a vaccine manufacturer for damages for a vaccine-related injury or death if such civil action is not barred by this part."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/300aa-22?type=usc&year=mostrecent&link-type=html"},"head":"§300aa–22. Standards of responsibility","tname":"The Public Health and Welfare","by":{"1":"26","2":"13"}},{"t":"law","label":"Judicial Improvements and Access to Justice Act, Pub. L. No. 100-702","url":"https://www.govinfo.gov/link/statute/102/4642","by":{"1":"16"}},{"t":"law","label":"Prison Litigation Reform Act., Pub. L. No. 104-134","url":"https://www.govinfo.gov/link/plaw/104/public/134","by":{"1":"3","2":"1"}},{"t":"rule","label":"Fed. R. Civ. P. 12","url":"https://www.law.cornell.edu/rules/frcp/rule_12","subs":["(b)(6)"],"by":{"1":"passim"}},{"t":"rule","label":"Fed. R. Civ. P. 41","url":"https://www.law.cornell.edu/rules/frcp/rule_41","subs":["(b)"],"by":{"1":"13, passim"}},{"t":"case","label":"Ackerman v. Mercy Behavior Health","cite":"617 Fed. Appx. 114","y":2015,"court":"3d Cir.","url":"https://www.courtlistener.com/c/Fed.%20Appx./617/114/","by":{"2":"15"}},{"t":"case","label":"Babbitt v. Sweet Home Chapter of Cmtys. for a Great Or.","cite":"515 U.S. 687","y":1995,"id":"1994/94-859","sc":1,"op":1,"sum":"Rejecting use of the noscitur canon when “the Senate went out of its way to add” a “broad word” to a statute.","sumSrc":"opinion","by":{"2":"20"}},{"t":"case","label":"(III) Cases—Continued: Booth v. Churner","cite":"532 U.S. 731","y":2001,"id":"2000/99-1964","sc":1,"sum":"The Court held that even though the prison grievance procedure did not provide for requested monetary relief, Booth was nonetheless required to exhaust administrative remedies before filing suit with respect to prison conditions.","sumSrc":"Oyez","by":{"2":"2, 14"}},{"t":"case","label":"Cutter v. Wilkinson","cite":"544 U.S. 709","y":2005,"id":"2004/03-9877","sc":1,"sum":"The Court held that, on its face, RLUIPA made an accommodation allowed by the First Amendment. The Court reasoned that the law was an effort to alleviate the \"government-created burden\" on religious exercise that prisoners faced. Nor did section three discriminate between mainstream and non-mainstream religions.","sumSrc":"Oyez","by":{"2":"31"}},{"t":"case","label":"Davis v. Kansas Dep’t of Corr.","cite":"507 F.3d 1246","y":2007,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/507/1246/","op":1,"by":{"2":"30"}},{"t":"case","label":"Douglas v. Yates","cite":"535 F.3d 1316","y":2008,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/535/1316/","op":1,"by":{"2":"16"}},{"t":"case","label":"Gemsco, Inc. v. Walling","cite":"324 U.S. 244","y":1945,"id":"scdb/1944-121","sc":1,"sum":"Under § 8 (f) of the Fair Labor Standards Act, the Administrator has authority, as a necessary means of making effective a minimum wage order for the embroideries industry, to prohibit industrial homework. Pp. 254, 269. 144 F. 2d 608, affirmed. CERTIORARI, 323 U. S. 695, to review a judgment affirming a wage order promulgated by the Administrator under the Fair Labor Standards Act. Messrs. Samuel S. Allan and …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"23"}},{"t":"case","label":"Higgins v. Carpenter","cite":"258 F.3d 797","y":2001,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/258/797/","by":{"2":"32"}},{"t":"case","label":"Kastner v. Texas","cite":"332 Fed. Appx. 980","y":2009,"court":"5th Cir.","url":"https://www.courtlistener.com/c/Fed.%20Appx./332/980/","by":{"2":"30"}},{"t":"case","label":"Mabon v. Madison Cnty.","cite":"2020 WL 236744","y":2020,"court":"W.D. Tenn. Jan. 15","by":{"2":"27"}},{"t":"case","label":"Marts v. Hines","cite":"117 F.3d 1504","y":1997,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/117/1504/","op":1,"by":{"2":"15"}},{"t":"case","label":"Mathis v. New York Life Ins. Co.","cite":"133 F.3d 546","y":1998,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/133/546/","by":{"2":"15"}},{"t":"case","label":"Miller v. French","cite":"530 U.S. 327","y":2000,"id":"1999/99-224","sc":1,"sum":"The Court held that Congress clearly intended to make operation of the PLRA's automatic stay provision mandatory, precluding courts from exercising their equitable power to enjoin the stay and that the PLRA does not violate separation of powers principles.","sumSrc":"Oyez","by":{"2":"2"}},{"t":"case","label":"Murphy v. Smith","cite":"138 S. Ct. 784","y":2018,"id":"2017/16-1067","sc":1,"sum":"A case in which the Court interpreted the parenthetical phrase “not to exceed 25 percent,” as used in 42 U.S.C. § 1997e(d)(2), to mean exactly 25 percent, thereby precluding the district court from exercising its discretion to allocate a lower percentage of the damage award to attorney's fees.","sumSrc":"Oyez","by":{"2":"14, 26"}},{"t":"case","label":"Northwest, Inc. v. Ginsberg","cite":"572 U.S. 273","y":2014,"id":"2013/12-462","sc":1,"sum":"The Court held that the Airline Deregulation Act preempts claims arising from a frequent flier complaint based on price, route, or air carrier service.","sumSrc":"Oyez","by":{"2":"16"}},{"t":"case","label":"Polanco v. Hopkins","cite":"510 F.3d 152","y":2007,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/510/152/","by":{"2":"32"}},{"t":"case","label":"Reagor v. Losacco","cite":"2019 WL 6327196","y":2019,"court":"N.D. Cal. Nov. 26","by":{"2":"27"}},{"t":"case","label":"Rivera v. Allin","cite":"144 F.3d 719","y":1998,"url":"https://www.courtlistener.com/c/F.3d/144/719/","by":{"2":"32"}},{"t":"case","label":"Rodriguez v. Cook","cite":"169 F.3d 1176","y":1999,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/169/1176/","by":{"2":"32"}},{"t":"case","label":"Ross v. Blake","cite":"136 S. Ct. 1850","y":2016,"id":"2015/15-339","sc":1,"sum":"The Court determined that the Prison Litigation Reform Act’s requirement to exhaust administrative remedies does not have a “special circumstances” exception.","sumSrc":"Oyez","by":{"2":"14"}},{"t":"case","label":"Rutan v. Republican Party of Ill.","cite":"497 U.S. 62","y":1990,"id":"1989/88-1872","sc":1,"sum":"In a 5-to-4 decision, the Court held that Governor Thompson's practices amounted to an unconstitutional patronage system. The Court found that employees would feel \"a significant obligation to support political positions held by their superiors\" in lieu of their true beliefs in order to progress up the career ladder.","sumSrc":"Oyez","by":{"2":"16"}},{"t":"case","label":"Schmidt v. Navarro","cite":"576 Fed. Appx. 897","y":2014,"court":"11th Cir.","url":"https://www.courtlistener.com/c/Fed.%20Appx./576/897/","by":{"2":"15"}},{"t":"case","label":"Shieh v. Kakita","cite":"517 U.S. 343","y":1996,"id":"1995/95-7587","sc":1,"sum":"For the reasons discussed in Martinv. Districtof Columbia Court of Appeals, 506 U. S. 1, Shieh is denied leave to proceed informa pauperis in the instant cases, and the Clerk is directed not to accept any further petitions for certiorari from him in noncriminal matters unless he pays the required docketing fee and submits his petition in compliance with this Court's Rule 33.1. This order will not prevent Shieh from …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"31, 32"}},{"t":"case","label":"Virginia Uranium, Inc. v. Warren","cite":"139 S. Ct. 1894","y":2019,"id":"2018/16-1275","sc":1,"op":1,"sum":"The Fourth Circuit’s judgment that the Atomic Energy Act does not preempt Virginia’s prohibition on uranium mining in the Commonwealth is affirmed.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"12"}},{"t":"case","label":"Wilson v. Yaklich","cite":"148 F.3d 596","y":1998,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/148/596/","by":{"2":"32"}},{"t":"case","label":"Yith v. Nielsen","cite":"881 F.3d 1155","y":2018,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/881/1155/","by":{"2":"16"}},{"t":"const","label":"Amendment V","clauses":[["grand-jury","Grand Jury Clause"],["double-jeopardy","Double Jeopardy Clause"],["self-incrimination","Self-Incrimination Clause"],["due-process-5","Due Process Clause (Fifth Amendment)"],["takings","Takings Clause"]],"text":"No person shall be held to answer for a capital, or otherwise infamous crime, unless on a presentment or indictment of a Grand Jury, except in cases arising in the land or naval forces, or in the Militia, when in actual service in time of War or public danger; nor shall any person be subject for the same offence to be twice put in jeopardy of life or limb; nor shall be compelled in any criminal case to be a witness against himself, nor be deprived of life, liberty, or property, without due process of law; nor shall private property be taken for public use, without just compensation.","by":{"2":"6, 27"}},{"t":"case","label":"Ackerman v. Mercy Behavior Health","cite":"617 F. App’x 114","y":2015,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/617/114/","by":{"3":"11"}},{"t":"case","label":"Air Wis. Airlines Corp. v. Hoeper","cite":"571 U.S. 237","y":2014,"id":"2013/12-315","sc":1,"sum":"The Court ruled that the Aviation and Transportation Security Act protects transportation officials from false statements, as long as the statements are not materially false within the ATSA context.","sumSrc":"Oyez","by":{"3":"4, 7"}},{"t":"case","label":"Christiansen v. Clarke","cite":"147 F.3d 655","y":1998,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/147/655/","by":{"3":"20"}},{"t":"case","label":"Holmberg v. Armbrecht","cite":"327 U.S. 392","y":1946,"id":"scdb/1945-049","sc":1,"sum":"1. Decision of a suit in a federal court to enforce a federally created equitable right is not controlled by the statute of limitations of the State of the forum. Guaranty Trust Co. v. York, 326 U. S. 99, distinguished. Accordingly, a class suit by creditors of a joint stock land bank to enforce the liability imposed upon shareholders of the bank by § 16 of the Federal Farm Loan Act is not barred by the state …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"3"}},{"t":"case","label":"Ladeairous v. Sessions","cite":"884 F.3d 1172","y":2018,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/884/1172/","by":{"3":"21"}},{"t":"case","label":"Luevano v. Wal-Mart Stores, Inc.","cite":"722 F.3d 1014","y":2013,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/722/1014/","by":{"3":"20"}},{"t":"case","label":"Okoro v. Bohman","cite":"164 F.3d 1059","y":1999,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/164/1059/","by":{"3":"10"}},{"t":"case","label":"Owens v. Isaac","cite":"487 F.3d 561","y":2007,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/487/561/","by":{"3":"17"}},{"t":"case","label":"Return Mail, Inc. v. U.S. Postal Serv.","cite":"139 S. Ct. 1853","y":2019,"id":"2018/17-1594","sc":1,"sum":"The Federal Government is not a “person” capable of petitioning the Patent Trial and Appeal Board to institute patent review proceedings under the Leahy-Smith America Invents Act.","sumSrc":"Holding (supremecourt.gov)","by":{"3":"15"}},{"t":"case","label":"Ricks v. Mackey","cite":"141 F.3d 1185","y":1998,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/141/1185/","by":{"3":"20"}},{"t":"case","label":"Schmidt v. Navarro","cite":"576 F. App’x 897","y":2014,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/576/897/","by":{"3":"12"}},{"t":"case","label":"Turley v. Gaetz","cite":"625 F.3d 1005","y":2010,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/625/1005/","sum":"Holding that no strike accrued where unexhausted claims were dismissed “at summary judgment”.","sumSrc":"brief:3","by":{"3":"18"}}]};